import ast
import base64
from pathlib import Path
from datetime import datetime
import shutil

HELPER = ''

def adaptar_painel(source):
    tree=ast.parse(source)
    if any(isinstance(n,ast.ImportFrom) and n.module=='savegame_auto' for n in tree.body):return source
    if not any(isinstance(n,ast.ClassDef) and n.name=='Window' for n in tree.body):raise RuntimeError('Classe Window não encontrada.')
    index=next((i for i,n in enumerate(tree.body) if isinstance(n,ast.If) and '__name__' in ast.unparse(n.test)),len(tree.body))
    hook=ast.parse('from savegame_auto import ativar as _ativar_savegame_auto_0419\n_ativar_savegame_auto_0419(globals())').body
    tree.body[index:index]=hook
    ast.fix_missing_locations(tree)
    return ast.unparse(tree)+'\n'

def adaptar_instalador(source):
    tree=ast.parse(source);found=False
    for n in ast.walk(tree):
        if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='arquivos' for t in n.targets) and isinstance(n.value,ast.List):
            if 'painel_jogadores.py' in [getattr(e,'value',None) for e in n.value.elts]:
                found=True
                if 'savegame_auto.py' not in [getattr(e,'value',None) for e in n.value.elts]:n.value.elts.append(ast.Constant(value='savegame_auto.py'))
    if not found:raise RuntimeError('Lista de módulos do instalador não reconhecida.')
    ast.fix_missing_locations(tree)
    return ast.unparse(tree)+'\n'

def main():
    root=Path(__file__).resolve().parent
    result={}
    for name,adapt in [('painel_jogadores.py',adaptar_painel),('gerar_instalador.py',adaptar_instalador)]:
        p=root/name
        if not p.is_file():raise RuntimeError('Arquivo ausente: '+name+'. Coloque o atualizador na pasta GeradorMapaAoE2.')
        result[name]=adapt(p.read_text(encoding='utf-8-sig'))
    result['savegame_auto.py']=base64.b64decode(HELPER).decode('utf-8')
    for name,code in result.items():compile(code,name,'exec')
    backup=root/'backups_atualizacoes'/datetime.now().strftime('%Y%m%d-%H%M%S-%f');backup.mkdir(parents=True)
    existed={n:(root/n).exists() for n in result}
    for n in result:
        if existed[n]:shutil.copy2(root/n,backup/n)
    try:
        for n,code in result.items():
            tmp=root/(n+'.tmp');tmp.write_text(code,encoding='utf-8');tmp.replace(root/n)
    except Exception:
        for n in result:
            if existed[n]:shutil.copy2(backup/n,root/n)
            else:(root/n).unlink(missing_ok=True)
        raise
    print('Detecção automática integrada. Backup:',backup)
    print('Execute py -3.12 gerar_atualizacao.py e informe 0.4.19 ou uma versão superior à última gerada.')
    print('Instale o novo instalador com o aplicativo fechado.')

if __name__=='__main__':
    try:main()
    except Exception as e:print('ERRO:',e);raise SystemExit(1)
